const task=(startTime,endTime,durationMinutes,type,label,title)=>({startTime,endTime,durationMinutes,type,label,title,completed:false});
const mcqs=(topic)=>[
 {question:`Which statement best describes ${topic}?`,options:[`It is directly related to ${topic}`,"It only stores passwords","It is a CSS framework","It replaces Git"],answer:0},
 {question:`What should you do after learning ${topic}?`,options:["Only watch again","Build and test a small implementation","Skip coding","Delete notes"],answer:1},
 {question:`Best way to verify your understanding of ${topic}?`,options:["Memorize title","Explain it, code it, test it","Ignore errors","Copy without running"],answer:1}
];
const makeDay=(day,course,topic,videos,project)=>({day,course,title:`Day ${day} — ${topic}`,topic,learningGoal:`Watch the assigned ${course} lectures, code the concept, complete MCQ and build the project.`,project:{title:project,status:"not-started",githubUrl:""},targetMinutes:280,videos:videos.map(v=>({...v,completed:false})),mcqs:mcqs(topic),quizAttempts:[],tasks:[task("09:00 PM","09:15 PM",15,"revision","Revision / Plan",`Revise and plan ${topic}`),task("09:15 PM","10:15 PM",60,"video","Course Videos",`Watch assigned videos: ${topic}`),task("10:15 PM","11:00 PM",45,"notes","Notes + Practice",`Write notes and reproduce examples for ${topic}`),task("11:10 PM","12:10 AM",60,"code","Coding Practice",`Code ${topic} yourself`),task("12:10 AM","12:50 AM",40,"quiz","MCQ + Recheck",`Complete MCQ and review wrong answers`),task("01:00 AM","01:40 AM",40,"project","Topic Project",project),task("01:40 AM","02:00 AM",20,"interview","Interview + Recap",`Explain ${topic} and answer interview questions`)],studyMinutes:0,score:0,feedback:""});
